tool_input.command:
L=/home/eslam/Downloads/TTFolder/quickflow-claude-loops/loops/testing/runs/001-quickflow/suite/test-phase-07/attempt-1/curl.log; U=http://localhost:8080/api/settings; H='Content-Type: application/json'
for p in TASKS HABITS LEARNING PLANS SETTINGS DASHBOARD; do
curl -sS -X PUT -H "$H" -d "{"displayName":"Eslam","planStartNotifications":false,"defaultPage":"$p"}" -w "
== A2 PUT defaultPage=$p HTTP %{http_code}
" $U --next -sS -w "
== A2 GET after PUT $p HTTP %{http_code}
" $U >> $L
done
curl -sS -X PUT -H "$H" -d '{"displayName":"Tester Q","planStartNotifications":true,"defaultPage":"HABITS"}' -w "
== A2 PUT name 'Tester Q' notif true HABITS HTTP %{http_code}
" $U --next -sS -w "
== A2 GET after PUT HTTP %{http_code}
" $U >> $L
curl -sS -X PUT -H "$H" -d '{"displayName":null,"planStartNotifications":true,"defaultPage":"DASHBOARD"}' -w "
== A2 PUT name null (clear) HTTP %{http_code}
" $U --next -sS -w "
== A2 GET after clear HTTP %{http_code}
" $U >> $L
tail -32 $L
